using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace DigitalEvidenceSystem.Web.Pages.Cases; [Authorize] public sealed class EditModel(EvidenceDbContext db, AuditService audit):PageModel { [BindProperty] public CaseFile Item {get;set;}=new(); public async Task<IActionResult> OnGetAsync(int id){var item=await db.Cases.FindAsync(id);if(item is null)return NotFound();Item=item;return Page();} public async Task<IActionResult> OnPostAsync(){if(!ModelState.IsValid)return Page();var current=await db.Cases.FindAsync(Item.Id);if(current is null)return NotFound();current.Title=Item.Title;current.Investigator=Item.Investigator;current.OpenedOn=Item.OpenedOn;current.Priority=Item.Priority;current.Status=Item.Status;current.CaseType=Item.CaseType;current.Description=Item.Description;current.UpdatedAt=DateTime.Now;if(current.Status=="Closed")current.ClosedOn??=DateTime.Now;await db.SaveChangesAsync();await audit.RecordAsync("Case updated",$"{current.CaseNumber} is now {current.Status}.","Case",current.Id.ToString());return RedirectToPage("Index");}}
